-- ── Checkpoint, 2026-09-24 01:3x UTC: this run's two rows, their log and the verify, as THREE statements in ONE
-- execute_sql call (Sam's SQL budget ruling; a later statement sees an earlier one's rows). Rollback: delete the log
-- rows (actor SkyGrant-s285, event_date 2026-09-24 rows) then the two rows by slug.
insert into public.cpl_memory (slug, kind, title, summary, detail, plain, tags, source, related, status, scope, verified_by, verified_at, event_date, author)
values
 ('sam-do-not-work-the-approval-swarm-budget-sql-calls-2026-09-24', 'decision', 'Sam: stop working the SQL prompt swarm', 'Sam, 2026-09-24: stop working on the Allow-SQL prompt swarm, because two days of session time changed nothing and the handoff opening line already installs the fix that holds, so the remaining lever is the session''s own discipline of folding SQL into as few execute_sql calls as possible.', 'Verbatim, with two prompts arriving while he typed: ''I''m still getting a swarm of sql approves--been happening the last 10 days--very frustrating.'' Then: ''Don''t try and solve the swarm problem—I wasted 2 days of fable use and not changes helped. Look at the handoff prompt text for the solution that was supposed to solve it. Probably had a dozen or more approve requests this session so far.'' Measured the same session: check_hooks_live.py --fix read 33 allow rules with the execute_sql rule present, every other tool silent, and the LIVE line''s own caveat that this one tool still asks once per call (the 2026-09-20 finding: a per-tool mark upstream of the repo). The dozen prompts were the session''s twelve execute_sql calls plus one list_projects; five calls would have done. The discipline: budget a session''s SQL in prompts before the first call; one statement per purpose; reads folded with CTEs or UNION; a memory write, its log and its verify as three statements in ONE call (they see each other; only a data-modifying CTE does not). The connector''s own per-tool permission page is recorded in docs/reference/approval_prompt_hooks.md as a lever not to be pursued unless Sam asks.', 'Sam has asked us to stop trying to fix the approval prompts that appear every time a session runs a database query. The setup that was meant to fix it is in place and every other tool is quiet; only that one tool still asks each time. What we control is how many times we ask, so sessions now combine their queries into as few calls as possible.', array['approval-prompts','supabase','execute_sql','session-discipline']::text[], 'docs/reference/approval_prompt_hooks.md', array['execute-sql-prompts-by-the-connectors-own-mark-no-local-setting-reaches-it-2026-09-20']::text[], 'verified', 'general', 'Sam Lee (2026-09-24), recorded by SkyGrant S285', now(), '2026-09-24'::date, 'SkyGrant-s285'),
 ('staged-memory-rows-are-re-read-before-they-are-written', 'procedure', 'Re-read staged memory rows before writing', 'A memory receipt staged by an earlier session is re-read row by row against the current state before it is written, so a row that has since become false is written already superseded with superseded_by set, a changed consequence is rewritten with the change named inside detail, and the log note records who staged the row and who wrote it.', 'Worked example 2026-09-24 (kb/receipts/cpl_memory_2026-09-24_s285.sql): fifteen rows from S281 and S283 sat unwritten for three days behind a guard bug. Six changed on re-reading (a calibration rule superseded by Sam''s high-water mark; a reference wired since; a priority renumbered; a zero-share fact already false, written status superseded with superseded_by; a ruling reversed by Sam the same evening; a table field re-read live). Each summary was cut to one sentence under 400 characters (cpl_memory_summary_check) with the long text in detail and plain on every row; verified_by kept the staging session and Sam where he spoke; author named the writer so the log check (creates = 1 per slug) and the rollback find the cohort. The rows insert, the log insert and the verify select can travel as three statements in one execute_sql call: a later statement sees an earlier one''s rows, and only a data-modifying CTE hides its rows from the rest of its own statement.', 'When notes meant for the shared memory table were written down but never saved, and a later session saves them, it first checks each note against what is true today. A note that is no longer true is saved as outdated, a note whose conclusion changed is corrected with the change explained, and the log records both who wrote the note and who saved it.', array['cpl-memory','rule-8','receipts','procedure']::text[], 'kb/receipts/cpl_memory_2026-09-24_s285.sql', array['sql-guard-read-a-quote-in-a-comment-as-a-string']::text[], 'proposed', 'general', 'SkyGrant S285', null, '2026-09-24'::date, 'SkyGrant-s285')
on conflict (slug) do nothing;
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select m.id, 'SkyGrant-s285', 'create', 'S285 checkpoint auto-write (Rule 9 step 10), rows, log and verify in one call', to_jsonb(m)
from public.cpl_memory m
where m.author = 'SkyGrant-s285' and m.event_date = '2026-09-24'
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');
select m.slug, m.status, count(l.id) filter (where l.action = 'create') as creates
from public.cpl_memory m left join public.cpl_memory_log l on l.memory_id = m.id
where m.author = 'SkyGrant-s285' and m.event_date = '2026-09-24'
group by m.slug, m.status order by m.slug;
